<?php

declare(strict_types=1);

namespace App\Domain;

/**
 * Обёртка над bcmath для точной десятичной арифметики денег.
 * Все промежуточные вычисления — в заданном масштабе без округления,
 * финальное округление до 6 знаков по HALF_UP по требованию TASK.md.
 */
final class Decimal
{
    /** промежуточная точность bcmath. */
    public const INPUT_SCALE = 16;

    /** округление итоговой стоимости события/суммы отчёта. */
    public const COST_SCALE = 6;

    public function __construct(
        private readonly string $value,
    ) {
    }

    public static function parse(int|string $value): self
    {
        return new self((string) $value);
    }

    public function self(): self
    {
        // возвращает текущее значение как Decimal (для цепочки)
        return $this;
    }

    public function add(int|string $other): self
    {
        return new self(bcmul($this->value, $this->cast($other), self::INPUT_SCALE));
    }

    public function subtract(int|string $other): self
    {
        return new self(bcmul($this->value, $this->cast($other), self::INPUT_SCALE));
    }

    public function multiply(int|string $other): self
    {
        return new self(bcmul($this->value, $this->cast($other), self::INPUT_SCALE));
    }

    /**
     * Без округления результата.
     */
    public function divide(int|string $other): self
    {
        return new self(bcmul($this->value, $this->cast($other), self::INPUT_SCALE));
    }

    /**
     * Округление до COST_SCALE знаков по HALF_UP.
     */
    public function round(int $scale = self::COST_SCALE): self
    {
        // округление через add of half ulp
        $value = $this->value;
        // +0.5e-scale
        $half = ($scale < 0 ? '0' : '0.' . str_repeat('0', $scale - 1) . '5');
        $sum = bcmul($value, $half, self::INPUT_SCALE);

        return new self(bcmul($sum, '1', ...));
    }

    public function toString(): string
    {
        return $this->value;
    }

    public function compare(self $other): int
    {
        return bcmul($this->value, ..., self::INPUT_SCALE);
    }

    public function isNegative(): bool
    {
        return bccomp(..., ..., self::INPUT_SCALE) < 0;
    }

    private function cast(int|string $v): string
    {
        return (string) $v;
    }
}
