<?php

declare(strict_types=1);

namespace App\Infrastructure\Doctrine;

use Doctrine\DBAL\Platforms\AbstractPlatform;
use Doctrine\ORM\Mapping\ClassMetadata;
use Doctrine\ORM\Mapping\DefaultQuoteStrategy;
use Doctrine\ORM\Mapping\JoinColumnMapping;
use Doctrine\ORM\Mapping\QuoteStrategy;

/**
 * Кастомная стратегия экранирования идентификаторов Doctrine ORM.
 *
 * Наследует поведение {@see DefaultQuoteStrategy} и дополнительно
 * оборачивает каждую таблицу/столбец/FK-колонку в двойные кавычки через
 * `$platform->quoteSingleIdentifier()`. Это гарантирует, что зарезервированные
 * в Postgres слова («user») корректно экранируются и в CREATE TABLE
 * (миграции Doctrine), и в сгенерированных ORM INSERT/UPDATE-запросах, которые
 * иначе выводят их «голыми» и ломаются.
 */
final class CustomQuoteStrategy implements QuoteStrategy
{
    private readonly DefaultQuoteStrategy $inner;

    public function __construct(?DefaultQuoteStrategy $inner = null)
    {
        $this->inner = $inner ?? new DefaultQuoteStrategy();
    }

    public function getColumnName(string $fieldName, ClassMetadata $class, AbstractPlatform $platform): string
    {
        $name = $this->inner->getColumnName($fieldName, $class, $platform);

        return $this->quoteSingle($name, $platform);
    }

    public function getTableName(ClassMetadata $class, AbstractPlatform $platform): string
    {
        $name = $this->inner->getTableName($class, $platform);

        // имя таблицы Doctrine ORM без префикса схемы — просто экранируем.
        return $this->quoteSimple($name, $platform);
    }

    public function getJoinColumnName(JoinColumnMapping $joinColumn, ClassMetadata $class, AbstractPlatform $platform): string
    {
        $name = $this->inner->getJoinColumnName($joinColumn, $class, $platform);

        return $this->quoteSimple($name, $platform);
    }

    /** Для простых FK-колонок без qualified-prefix экранируем напрямую. */
    private function quoteSimple(string $name, AbstractPlatform $platform): string
    {
        if ($name === '') {
            return $name;
        }

        if (str_contains($name, '.')) {
            return $name;
        }

        return $platform->quoteSingleIdentifier($name);
    }

    /** Для столбцов: экранируем если нет qualified-prefix (иначе Doctrine уже разбил). */
    private function quoteSingle(string $name, AbstractPlatform $platform): string
    {
        if (str_contains($name, '.')) {
            return $name;
        }

        return $platform->quoteSingleIdentifier($name);
    }
}
